  const LINES=Object.fromEntries(Object.entries(VOICES).flatMap(([speaker,v])=>['before','ordinary','after','law','pair'].flatMap(stage=>v[stage].map((text,i)=>[speaker+':'+stage+':'+i,{speaker,stage,text}]))));
